36:     }
37: 
38:     /**
39:      * @param e
40:      */
41:     @PreAuthorize("hasRole(@configHolder.getSuperAdminRoleName())"
42:         + " or (#e.id == null and hasPermission(#e, 'CREATE'))"
43:         + " or (#e.id != null and hasPermission(#e, 'UPDATE'))")
44:     public void saveOrUpdate(E e) {
45:         dao.saveOrUpdate(e);
46:     }
47: 
48:     /**
49:      * @param jsonObject
50:      * @param entity
51:      * @return
52:      * @throws IOException
53:      * @throws JsonProcessingException
54:      */
55:     @PreAuthorize("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(#entity, 'UPDATE')")
56:     public E updatePartialWithJsonNode(E entity, JsonNode jsonObject, ObjectMapper objectMapper) throws IOException, JsonProcessingException {
57:         // update "partially". credits go to http://stackoverflow.com/a/15145480
58:         entity = objectMapper.readerForUpdating(entity).readValue(jsonObject);
59:         this.saveOrUpdate(entity);
