70:     @Transactional(readOnly = true)
71:     public E findById(Integer id) {
72:         return dao.findById(id);
73:     }
74: 
75:     /**
76:      * Return a proxy of the object (without hitting the database). This should
77:      * only be used if it is assumed that the object really exists and where
78:      * non-existence would be an actual error.
79:      *
80:      * @param id
81:      */
82:     @PostAuthorize("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(returnObject, 'READ')")
83:     @Transactional(readOnly = true)
84:     public E loadById(int id) {
85:         return dao.loadById(id);
86:     }
