88:     /**
89:      *
90:      */
91:     @PostFilter("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(filterObject, 'READ')")
92:     @Transactional(readOnly = true)
93:     public List<E> findAll() {
94:         return dao.findAll();
95:     }
96: 
97:     /**
98:      * Returns all entities, but possibly with only the passed fields set with actual values.
99:      */
100:     @PostFilter("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(filterObject, 'READ')")
101:     public List<E> findAllRestricted(MultiValueMap<String, String> restrictToRequest) {
102:         List<String> restrictFields = EntityUtil.determineRestrictFields(restrictToRequest, getEntityClass());
103:         return dao.findByCriteriaRestricted(restrictFields);
104:     }
105: 
106:     /**
107:      * Finds all entities that match the given filter (multi value map).
108:      * <p>
109:      * Each key in the multi value map is the name of a field/property of the
110:      * entity. These values may be case insensitive! Each field name is mapped
111:      * to a list of values (passed as Strings).
112:      * <p>
113:      * Fields that do not exist in the entity will be ignored.
114:      * <p>
115:      * Example:
116:      * <p>
117:      * <pre>
118:      * int=['1','2']
119:      * string=['foo']
120:      * bool1=['0']
121:      * bool2=['true']
122:      * </pre>
123:      * <p>
124:      * would be translated to a filter like (values are casted to the target type of the field)
125:      * <p>
126:      * <pre>
127:      * (int == 1 || int == 2) &amp;&amp; (string == 'foo') &amp;&amp; (bool1 == false) &amp;&amp; (bool2 == true)
128:      * </pre>
129:      * <p>
130:      * and return all entities that match this condition.
131:      * <p>
132:      * This will only work on simple properties of an entity.
133:      * <p>
134:      * The optional special key {@value EntityUtil#RESTRICT_FIELDS_PARAM} can contain a
135:      * comma separated list of fieldNames you want to be filled with actual values. If you
136:      * e.g. pass <code>output:only=id,Name</code>, the returned object will have all other
137:      * fields being set to null, except for <code>id</code> and <code>name</code> (Notice
138:      * how casing does not matter).
139:      *
140:      * @param requestedFilter
141:      * @return
142:      */
143:     @PostFilter("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(filterObject, 'READ')")
144:     @Transactional(readOnly = true)
145:     public List<E> findBySimpleFilter(MultiValueMap<String, String> requestedFilter) {
146: 
147:         List<String> restrictFields = EntityUtil.determineRestrictFields(requestedFilter, getEntityClass());
148:         requestedFilter.remove(EntityUtil.RESTRICT_FIELDS_PARAM);
149: 
150:         MultiValueMap<String, Object> origFieldNamesToCastedValues = EntityUtil
151:             .validFieldNamesWithCastedValues(requestedFilter, getEntityClass());
152: 
153:         // start with an empty list
154:         List<E> results = new ArrayList<>();
155: 
156:         List<Criterion> orPredicates = new ArrayList<>();
157: 
158:         if (!origFieldNamesToCastedValues.isEmpty()) {
159:             for (Map.Entry<String, List<Object>> entry : origFieldNamesToCastedValues.entrySet()) {
160:                 // if there are multiple values for a field name, we'll check
161:                 // for equality and connect them with OR
162:                 List<Criterion> eqExpressions = new ArrayList<>();
163:                 List<Object> fieldValues = entry.getValue();
164: 
165:                 for (Object fieldValue : fieldValues) {
166:                     final SimpleExpression eq = Restrictions.eq(entry.getKey(), fieldValue);
167:                     eqExpressions.add(eq);
168:                 }
169: 
170:                 if (!eqExpressions.isEmpty()) {
171:                     final Criterion[] eqArray = eqExpressions.toArray(new Criterion[0]);
172:                     final Disjunction or = Restrictions.or(eqArray);
173:                     orPredicates.add(or);
174:                 }
175:             }
176: 
177:             if (!orPredicates.isEmpty()) {
178:                 final Criterion[] orArray = orPredicates.toArray(new Criterion[0]);
179:                 final Conjunction and = Restrictions.and(orArray);
180:                 results = dao.findByCriteriaRestricted(restrictFields, and);
181:             }
182:         }
183: 
184:         return results;
185:     }
186: 
