214:     @Transactional(readOnly = true)
215:     public List<E> findAllWithCollectionContaining(String fieldName, PersistentObject subElement) {
216:         return dao.findAllWithCollectionContaining(fieldName, subElement);
217:     }
218: 
219:     /**
220:      * @param e
221:      */
222:     @PreAuthorize("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(#e, 'DELETE')")
223:     public void delete(E e) {
224:         dao.delete(e);
225:     }
226: 
227: }

