152:         } else if (singular.endsWith(String.valueOf(LAST_CHAR_S))
153:             || singular.endsWith(String.valueOf(LAST_CHAR_X))
154:             || singular.endsWith(String.valueOf(LAST_CHAR_Z))
155:             || singular.endsWith(LAST_CHARS_CH)
156:             || singular.endsWith(LAST_CHARS_SH)) {
