428:         Response response = sendRequest(mutableRequest);
429: 
430:         // intercept the response (if needed)
431:         Response interceptedResponse = ogcMessageDistributor
432:             .distributeToResponseInterceptor(mutableRequest, response, message);
433: 
434:         // finally filter the white-listed response headers
435:         // TODO: Move to global proxy class
436:         HttpHeaders forwardingHeaders = getResponseHeadersToForward(
437:             interceptedResponse.getHeaders()
438:         );
439:         interceptedResponse.setHeaders(forwardingHeaders);
440: 
441:         return interceptedResponse;
442:     }
