475:     private OgcMessage getOgcMessage(MutableHttpServletRequest mutableRequest)
476:         throws InterceptorException, IOException {
477: 
478:         LOG.trace("Building the OGC message from the given request.");
479: 
480:         OgcMessage ogcMessage = new OgcMessage();
481: 
482:         String requestService = MutableHttpServletRequest.getRequestParameterValue(
483:             mutableRequest, OgcEnum.Service.SERVICE.toString());
484:         String requestOperation = MutableHttpServletRequest.getRequestParameterValue(
485:             mutableRequest, OgcEnum.Operation.OPERATION.toString());
486:         String requestEndPoint = MutableHttpServletRequest.getRequestParameterValue(
487:             mutableRequest, OgcEnum.EndPoint.getAllValues());
488: 
489:         // always use the custom_endpoint as endpoint and not one of the other options to successfully determine
490:         // the base URI
491:         if (!StringUtils.isEmpty(requestService) && requestService.equalsIgnoreCase("wmts")) {
492:             requestEndPoint = MutableHttpServletRequest.getRequestParameterValue(
493:                 mutableRequest, OgcEnum.EndPoint.CUSTOM_ENDPOINT.toString());
494:         }
495: 
496:         // check for RESTful WMTS request
497:         if (StringUtils.isEmpty(requestService) && StringUtils.isEmpty(requestOperation)) {
498:             if (WmtsUtil.isRestfulWmtsRequest(mutableRequest)) {
499:                 requestService = ServiceType.WMTS.toString();
500:                 if (WmtsUtil.isRestfulWmtsGetFeatureinfo(mutableRequest)) {
501:                     requestOperation = OperationType.GET_FEATURE_INFO.toString();
502:                 } else if (WmtsUtil.isRestfulWmtsGetTile(mutableRequest)) {
503:                     requestOperation = OperationType.GET_TILE.toString();
504:                 } else {
505:                     requestOperation = OperationType.GET_CAPABILITIES.toString();
506:                 }
507:             }
508:         }
509: 
510:         if (StringUtils.isEmpty(requestService) ||
511:             StringUtils.isEmpty(requestOperation) ||
512:             StringUtils.isEmpty(requestEndPoint)) {
513:             if (StringUtils.isEmpty(requestEndPoint) && StringUtils.equals(requestService, "WPS")) {
514:                 LOG.trace("Will use empty string as endpoint for WPS");
515:             } else if (!StringUtils.isEmpty(requestEndPoint) &&
516:                 !StringUtils.isEmpty(MutableHttpServletRequest.getRequestParameterValue(
517:                     mutableRequest, USE_REFLECT_PARAM))
518:             ) {
519:                 LOG.trace("Will use WMS reflector endpoint of GeoServer");
520:                 requestService = ServiceType.WMS.toString();
521:                 requestOperation = OperationType.GET_MAP.toString();
522:             } else {
523:                 throw new InterceptorException("Couldn't find all required OGC " +
524:                     "parameters (SERVICE, REQUEST, ENDPOINT). Please check the " +
525:                     "validity of the request.");
526:             }
527:         }
528: 
529:         if (StringUtils.isNotEmpty(requestService)) {
530:             ogcMessage.setService(OgcEnum.ServiceType.fromString(requestService));
531:             LOG.trace("Successfully set the service: " +
532:                 OgcEnum.ServiceType.fromString(requestService));
533:         } else {
534:             LOG.debug("No service found.");
535:         }
536: 
537:         if (StringUtils.isNotEmpty(requestOperation)) {
538:             ogcMessage.setOperation(OgcEnum.OperationType.fromString(requestOperation));
539:             LOG.trace("Successfully set the operation: " +
540:                 OgcEnum.OperationType.fromString(requestOperation));
541:         } else {
542:             LOG.debug("No operation found.");
543:         }
544: 
545:         if (StringUtils.isNotEmpty(requestEndPoint)) {
546:             ogcMessage.setEndPoint(requestEndPoint);
547:             LOG.trace("Successfully set the endPoint: " + requestEndPoint);
548:         } else {
549:             LOG.debug("No endPoint found.");
550:         }
551: 
552:         InterceptorRule mostSpecificRequestRule = getMostSpecificRule(requestService,
553:             requestOperation, requestEndPoint, HttpEnum.EventType.REQUEST.toString());
554:         InterceptorRule mostSpecificResponseRule = getMostSpecificRule(requestService,
555:             requestOperation, requestEndPoint, HttpEnum.EventType.RESPONSE.toString());
556: 
557:         if (mostSpecificRequestRule != null) {
558:             ogcMessage.setRequestRule(mostSpecificRequestRule.getRule());
559:             LOG.trace("Successfully set the requestRule: " +
560:                 mostSpecificRequestRule.getRule());
561:         } else {
562:             LOG.debug("No interceptor rule found for the request.");
563:         }
564: 
565:         if (mostSpecificResponseRule != null) {
566:             ogcMessage.setResponseRule(mostSpecificResponseRule.getRule());
567:             LOG.trace("Successfully set the responseRule: " +
568:                 mostSpecificResponseRule.getRule());
569:         } else {
570:             LOG.debug("No interceptor rule found for the response.");
571:         }
572: 
573:         LOG.trace("Successfully build the OGC message: " + ogcMessage);
574: 
575:         return ogcMessage;
576:     }
