719:     /**
720:      * @param message
721:      * @throws URISyntaxException
722:      * @throws InterceptorException
723:      */
724:     private URI getGeoServerBaseURI(OgcMessage message, boolean useWmsReflector) throws URISyntaxException,
725:         InterceptorException {
726: 
727:         LOG.debug("Finding the GeoServer base URI by the provided EndPoint: " +
728:             message.getEndPoint());
729: 
730:         // get the namespace from the qualified endPoint name
731:         String geoServerNamespace = getGeoServerNameSpace(message.getEndPoint());
732: 
733:         LOG.trace("Found the following GeoServer namespace set in the "
734:             + "EndPoint: " + geoServerNamespace);
735: 
736:         // set the GeoServer base URL
737:         URI geoServerBaseUri = getGeoServerBaseURIFromNameSpace(geoServerNamespace, useWmsReflector, message.isWms());
738: 
739:         LOG.debug("The corresponding GeoServer base URI is: " + geoServerBaseUri);
740: 
741:         return geoServerBaseUri;
742:     }
