22: import java.util.HashSet;
23: import java.util.Set;
24: 
25: import static org.apache.logging.log4j.LogManager.getLogger;
26: 
27: /**
28:  * @author Nils Bühner
29:  */
30: public class ShogunCoreAuthenticationProvider implements AuthenticationProvider {
31: 
32:     /**
33:      * The Logger
34:      */
35:     private static final Logger LOG = getLogger(ShogunCoreAuthenticationProvider.class);
36: 
37:     @Autowired
38:     private UserDao<User> userDao;
39: 
40:     @Autowired
41:     private PasswordEncoder passwordEncoder;
42: 
43:     /**
44:      * This method has to be {@link Transactional} to allow that associated entities
45:      * can be fetched lazily.
46:      *
47:      * @see org.springframework.security.authentication.AuthenticationProvider#authenticate(org.springframework.security.core.Authentication)
48:      */
49:     @Override
50:     @Transactional(value = "transactionManager", readOnly = true)
51:     public Authentication authenticate(Authentication authentication)
52:         throws AuthenticationException {
53: 
54:         // prepare an exception
55:         final String exceptionMessage = "User and password do not match.";
56: 
57:         // get username/password
58:         String accountName = authentication.getName();
59:         String rawPassword = (String) authentication.getCredentials();
60: 
61:         LOG.debug("Trying to authenticate User '" + accountName + "'");
62: 
63:         User user = userDao.findByAccountName(accountName);
64: 
65:         // prepare set of authorities
66:         Set<GrantedAuthority> grantedAuthorities = new HashSet<GrantedAuthority>();
67: 
68:         String encryptedPassword = null;
69: 
70:         if (user == null) {
71:             LOG.warn("No user for account name '" + accountName + "' could be found.");
72:             throw new UsernameNotFoundException(exceptionMessage);
73:         } else if (!user.isActive()) {
74:             LOG.warn("The user with the account name '" + accountName + "' is not active.");
75:             throw new DisabledException(exceptionMessage);
76:         } else {
77: 
78:             encryptedPassword = user.getPassword();
79: 
80:             // check if rawPassword matches the hash from db
81:             if (passwordEncoder.matches(rawPassword, encryptedPassword)) {
82: 
83:                 Set<Role> allUserRoles = getAllUserRoles(user);
84: 
85:                 // create granted authorities for the security context
86:                 for (Role role : allUserRoles) {
87:                     grantedAuthorities.add(new SimpleGrantedAuthority(role.getName()));
88:                 }
89: 
90:             } else {
91:                 LOG.warn("The given password for user '" + accountName + "' does not match.");
92:                 throw new BadCredentialsException(exceptionMessage);
93:             }
94: 
95:         }
96: 
97:         // Create corresponding token to forward in Spring Security's filter
98:         // chain. We will use the SHOGun-Core user as the principal.
99:         Authentication authResult = null;
100:         if (grantedAuthorities.isEmpty()) {
101:             // if the user has no authorities, we will build the
102:             // UsernamePasswordAuthenticationToken without authorities, which
103:             // leads to an unauthenticated user, i.e. isAuthenticated() of
104:             // authenticationToken will return false afterwards.
105:             LOG.warn("The user '" + accountName + "' has no authorities and will thereby NOT be authenticated.");
106:             authResult = new UsernamePasswordAuthenticationToken(user, encryptedPassword);
107:         } else {
108:             // if we pass some grantedAuthorities, isAuthenticated() of
109:             // authenticationToken will return true afterwards
110:             authResult = new UsernamePasswordAuthenticationToken(user, encryptedPassword, grantedAuthorities);
111: 
112:             LOG.debug("The user '" + accountName
113:                 + "' got the following (explicit) roles: "
114:                 + StringUtils.join(getRawRoleNames(grantedAuthorities), ", "));
115:         }
116: 
117:         final boolean isAuthenticated = authResult.isAuthenticated();
118:         final String authLog = isAuthenticated ? "has succesfully" : "has NOT";
119:         LOG.info("The user '" + accountName + "' " + authLog + " been authenticated.");
120: 
121:         return authResult;
122:     }
123: 
124:     /**
125:      * @see org.springframework.security.authentication.AuthenticationProvider#supports
126:      * (java.lang.Class)
127:      */
128:     @Override
129:     public boolean supports(Class<?> authentication) {
130:         return (UsernamePasswordAuthenticationToken.class
131:             .isAssignableFrom(authentication));
132:     }
133: 
134:     /**
135:      * @param user
136:      * @return
137:      */
138:     private Set<Role> getAllUserRoles(User user) {
139:         Set<Role> allUserRoles = new HashSet<Role>();
140: 
141:         // user roles
142:         if (user != null) {
143:             allUserRoles.addAll(user.getRoles());
144:         } else {
145:             return allUserRoles;
146:         }
147: 
148:         Set<UserGroup> userGroups = user.getUserGroups();
149:         // userGroup roles
150:         if (userGroups != null) {
151:             for (UserGroup userGroup : userGroups) {
152:                 allUserRoles.addAll(userGroup.getRoles());
153:             }
154:         }
155:         return allUserRoles;
156:     }
157: 
158:     /**
159:      * @param grantedAuthorities
160:      * @return
161:      */
162:     private Set<String> getRawRoleNames(Set<GrantedAuthority> grantedAuthorities) {
163:         Set<String> grantedRoles = new HashSet<String>();
164:         for (GrantedAuthority auth : grantedAuthorities) {
165:             grantedRoles.add(auth.getAuthority());
166:         }
167:         return grantedRoles;
168:     }
169: 
170:     /**
171:      * @return the passwordEncoder
172:      */
173:     public PasswordEncoder getPasswordEncoder() {
174:         return passwordEncoder;
175:     }
176: 
177:     /**
178:      * @param passwordEncoder the passwordEncoder to set
179:      */
180:     public void setPasswordEncoder(PasswordEncoder passwordEncoder) {
181:         this.passwordEncoder = passwordEncoder;
182:     }
