537:     /**
538:      * A helper method returning some interceptor rules (out of a predefined
539:      * String array).
540:      * <p>
541:      * Note: In order to mock the behaviour of findAllRulesForServiceAndEvent()
542:      * this must return the rules ordered by endPoint and operation.
543:      *
544:      * @return
545:      */
546:     private static List<InterceptorRule> getTestInterceptorRulesForServiceAndEvent(
547:         String service, String event) {
548: 
549:         List<InterceptorRule> mockedRules = new ArrayList<InterceptorRule>();
550: 
551:         if (OgcEnum.ServiceType.fromString(service) == null ||
552:             HttpEnum.EventType.fromString(event) == null) {
553:             return mockedRules;
554:         }
555: 
556:         String[] testRules = new String[]{
557:             service + ",,," + event + ",DENY",
558:             service + ",GetMap,bvb:hummels," + event + ",ALLOW",
559:             service + ",GetFeatureInfo,bvb:shinji," + event + ",MODIFY",
560:             service + ",GetMap,bvb:shinji," + event + ",DENY",
561:             service + ",GetCapabilities,bvb:shinji," + event + ",DENY",
562:             service + ",DescribeFeatureType,," + event + ",ALLOW",
563:             service + ",GetMap,," + event + ",ALLOW",
564:             service + ",GetFeatureInfo,," + event + ",DENY",
565:             service + ",GetStyles,bvb:yarmolenko," + event + ",MODIFY",
566:         };
567: 
568:         for (String testRule : testRules) {
569:             String[] ruleSpecs = testRule.split(",");
570:             InterceptorRule rule = new InterceptorRule();
