559:             service + ",GetFeatureInfo,bvb:shinji," + event + ",MODIFY",
560:             service + ",GetMap,bvb:shinji," + event + ",DENY",
561:             service + ",GetCapabilities,bvb:shinji," + event + ",DENY",
562:             service + ",DescribeFeatureType,," + event + ",ALLOW",
563:             service + ",GetMap,," + event + ",ALLOW",
564:             service + ",GetFeatureInfo,," + event + ",DENY",
565:             service + ",GetStyles,bvb:yarmolenko," + event + ",MODIFY",
566:         };
567: 
568:         for (String testRule : testRules) {
569:             String[] ruleSpecs = testRule.split(",");
