14: /**
15:  * A JPA converter that can be used to convert jsonb fields into a map. Currently only works with 'simple' json
16:  * content (only one level objects like {"name": "peter", "someprop": 345}).
17:  * <p>
18:  * Please note that you'll need to switch to pgjdbc-ng from https://github.com/impossibl/pgjdbc-ng instead of using the
19:  * standard postgres driver.
20:  * <p>
21:  * Please also note that if you want optimal performance you'll need to add an index manually, hibernate can only create
22:  * btree indexes.
23:  */
24: @Converter(autoApply = true)
25: public class SimpleJsonbConverter implements AttributeConverter<Map<String, String>, String> {
26: 
27:     private static final Logger LOG = getLogger(SimpleJsonbConverter.class);
28: 
29:     @Override
30:     public String convertToDatabaseColumn(Map<String, String> attribute) {
31:         ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
32:         try {
33:             return (mapper.writeValueAsString(attribute));
34:         } catch (Exception e) {
35:             LOG.warn("Could not convert JSON value to PostgreSQL format: " + e.getMessage());
36:             LOG.debug("Stack trace: " + e.toString());
37:         }
38:         return "{}";
39:     }
40: 
41:     @Override
42:     public Map<String, String> convertToEntityAttribute(String dbData) {
43:         ShogunCoreJsonObjectMapper parser = new ShogunCoreJsonObjectMapper();
44:         try {
45:             return parser.readValue(dbData, HashMap.class);
46:         } catch (IOException e) {
47:             LOG.warn("Could not convert JSON value from PostgreSQL format: " + e.getMessage());
48:             LOG.debug("Stack trace: " + e.toString());
49:         }
50:         return new HashMap<>();
51:     }
