import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.CriteriaQuery;
import jakarta.persistence.criteria.Predicate;
import jakarta.persistence.criteria.Root;

/**
 * One restriction of a DAO query, built with the JPA Criteria API.
 * <p>
 * This replaces the legacy Hibernate {@code Criterion} API (which was removed
 * in Hibernate ORM 6) and follows the design of the Spring Data JPA
 * {@code Specification} interface: implementors receive the {@link Root},
 * {@link CriteriaQuery} and {@link CriteriaBuilder} of the query that is
 * currently being built and return a single {@link Predicate} (or {@code null}
 * to apply no restriction).
 *
 * @param <E> The entity type the query is built for
 */
@FunctionalInterface
public interface QueryRestriction<E> {

    /**
     * Builds the restriction as a JPA Criteria {@link Predicate}.
     *
     * @param root  The root of the criteria query, referring to the queried
     *              entity type
     * @param query The criteria query that is currently being built
     * @param cb    The criteria builder to create the predicate with
     * @return The predicate representing this restriction, or {@code null} if
     * no restriction shall be applied
     */
    Predicate toPredicate(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb);
}

