/**
 * A sort order of a DAO query: a property name and a direction.
 * <p>
 * This replaces the legacy Hibernate {@code Order} class (which was removed
 * in Hibernate ORM 6).
 */
public final class SortOrder {

    /**
     * The name of the property to sort by.
     */
    private final String property;

    /**
     * Whether the sort direction is ascending.
     */
    private final boolean ascending;

    /**
     * Creates a new sort order.
     *
     * @param property  The name of the property to sort by
     * @param ascending Whether the sort direction is ascending
     */
    private SortOrder(String property, boolean ascending) {
        this.property = property;
        this.ascending = ascending;
    }

    /**
     * Creates an ascending sort order for the given property.
     *
     * @param property The name of the property to sort by
     * @return An ascending sort order
     */
    public static SortOrder asc(String property) {
        return new SortOrder(property, true);
    }

    /**
     * Creates a descending sort order for the given property.
     *
     * @param property The name of the property to sort by
     * @return A descending sort order
     */
    public static SortOrder desc(String property) {
        return new SortOrder(property, false);
    }

    /**
     * @return The name of the property to sort by
     */
    public String getProperty() {
        return property;
    }

    /**
     * @return Whether the sort direction is ascending
     */
    public boolean isAscending() {
        return ascending;
    }
}

