package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.UserGroup;
import de.terrestris.shoguncore.model.security.PermissionCollection;
import de.terrestris.shoguncore.paging.PagingResult;
import de.terrestris.shoguncore.util.entity.EntityUtil;
import org.apache.commons.lang3.reflect.FieldUtils;
import org.apache.logging.log4j.Logger;
import org.hibernate.HibernateException;
import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.hibernate.proxy.HibernateProxy;
import org.joda.time.DateTime;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Repository;

import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.CriteriaQuery;
import jakarta.persistence.criteria.Join;
import jakarta.persistence.criteria.Order;
import jakarta.persistence.criteria.Predicate;
import jakarta.persistence.criteria.Root;
import java.io.Serializable;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.apache.logging.log4j.LogManager.getLogger;

/**
 * The superclass for all data access objects. Provides basic CRUD
 * functionality and a logger instance for all subclasses.
 *
 * @author Nils Bühner
 */
@Repository("genericDao")
public class GenericHibernateDao<E extends PersistentObject, ID extends Serializable> {

    /**
     * The LOGGER instance (that will be available in all subclasses)
     */
    protected static final Logger logger = getLogger(GenericHibernateDao.class);

    /**
     * Represents the class of the entity
     */
    private final Class<E> entityClass;

    @Value("${hibernate.cache.use_query_cache}")
    private Boolean useQueryCache;
    /**
     * Hibernate SessionFactory
     */
    @Autowired
    private SessionFactory sessionFactory;

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public GenericHibernateDao() {
        this((Class<E>) PersistentObject.class);
    }

    /**
     * Constructor
     *
     * @param clazz
     */
    protected GenericHibernateDao(Class<E> clazz) {
        this.entityClass = clazz;
    }

    /**
     * Obtains the current session.
     *
     * @return
     */
    private Session getSession() {
        return sessionFactory.getCurrentSession();
    }

    /**
     * Return the real object from the database. Returns null if the object does
     * not exist.
     *
     * @param id
     * @return The object from the database or null if it does not exist
     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
     */
    public E findById(ID id) {
        logger.trace("Finding " + entityClass.getSimpleName() + " with ID " + id);
        return getSession().get(entityClass, id);
    }

    /**
     * Returns a list of entity objects that have field named
     * <code>fieldName</code>, which has an object <code>fieldEntity</code>
     * as value.
     *
     * @param fieldName    The name of the field
     * @param fieldEntity  The element that should be set as value
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    public List<E> findAllWhereFieldEquals(String fieldName, Object fieldEntity,
                                           QueryRestriction<E>... restrictions) {

        Class<?> fieldEntityType = null;

        if (fieldEntity != null) {
            fieldEntityType = fieldEntity.getClass();
        }

        final boolean isField = EntityUtil.isField(entityClass, fieldName, fieldEntityType, true);

        if (!isField) {
            String errorMsg = String.format(
                "There is no field '%s' in the type '%s' that accepts instances of '%s'",
                fieldName,
                entityClass.getName(),
                fieldEntityType.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> criteriaQuery = criteriaBuilder.createQuery(entityClass);
        final Root<E> root = criteriaQuery.from(entityClass);

        criteriaQuery.select(root).distinct(true);

        final List<Predicate> predicates = new ArrayList<>();
        if (fieldEntity == null) {
            predicates.add(criteriaBuilder.isNull(root.get(fieldName)));
        } else {
            predicates.add(criteriaBuilder.equal(root.get(fieldName), fieldEntity));
        }
        addRestrictionsToPredicates(root, criteriaQuery, criteriaBuilder, restrictions, predicates);
        criteriaQuery.where(asPredicateArray(predicates));

        return list(criteriaQuery);
    }

    /**
     * Returns a list of entity objects that have a collection named
     * <code>fieldName</code>, which contains the passed
     * <code>subElement</code>.
     * <p>
     * The can e.g. be used to return all applications that contain a certain layer.
     *
     * @param fieldName    The name of the collection field
     * @param subElement   The element that should be contained in the collection
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    public List<E> findAllWithCollectionContaining(String fieldName, PersistentObject subElement,
                                                   QueryRestriction<E>... restrictions) {
        final Class<? extends PersistentObject> subElementType = subElement.getClass();

        final boolean isCollectionField = EntityUtil.isCollectionField(entityClass, fieldName, subElementType, true);

        if (!isCollectionField) {
            String errorMsg = String.format(
                "There is no collection field '%s' with element type '%s' in the type '%s'",
                fieldName,
                subElementType.getName(),
                entityClass.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> criteriaQuery = criteriaBuilder.createQuery(entityClass);
        final Root<E> root = criteriaQuery.from(entityClass);

        criteriaQuery.select(root).distinct(true);

        // join the collection and restrict on the id of the joined subelement
        final Join<E, ?> sub = root.join(fieldName);

        final List<Predicate> predicates = new ArrayList<>();
        predicates.add(criteriaBuilder.equal(sub.get("id"), subElement.getId()));
        addRestrictionsToPredicates(root, criteriaQuery, criteriaBuilder, restrictions, predicates);
        criteriaQuery.where(asPredicateArray(predicates));

        return list(criteriaQuery);
    }

    /**
     * Return a proxy of the object (without hitting the database). This should
     * only be used if it is assumed that the object really exists and where
     * non-existence would be an actual error.
     *
     * @param id
     * @return
     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
     */
    public E loadById(ID id) {
        logger.trace("Loading " + entityClass.getSimpleName() + " with ID " + id);
        return getSession().load(entityClass, id);
    }

    /**
     * Returns all Entities by calling findByCriteria(), i.e. without arguments.
     *
     * @return All entities
     * @see GenericHibernateDao#findByCriteria(QueryRestriction...)
     */
    public List<E> findAll() throws HibernateException {
        logger.trace("Finding all instances of " + entityClass.getSimpleName());
        return findByCriteria();
    }

    /**
     * Saves or updates the passed entity.
     *
     * @param e The entity to save or update in the database.
     */
    public void saveOrUpdate(E e) {
        final Integer id = e.getId();
        final boolean hasId = id != null;
        String createOrUpdatePrefix = hasId ? "Updating" : "Creating a new";
        String idSuffix = hasId ? " with ID " + id : "";

        logger.trace(createOrUpdatePrefix + " instance of " + entityClass.getSimpleName()
            + idSuffix);

        e.setModified(DateTime.now());
        getSession().saveOrUpdate(e);
    }

    /**
     * Deletes the passed entity.
     *
     * @param e The entity to remove from the database.
     */
    public void delete(E e) {
        logger.trace("Deleting " + entityClass.getSimpleName() + " with ID " + e.getId());
        getSession().delete(e);
    }

    /**
     * Unproxy the entity (and eagerly fetch properties).
     */
    @SuppressWarnings("unchecked")
    public E unproxy(E e) {
        if (e == null) {
            throw new NullPointerException("Entity passed for initialization is null");
        }

        Hibernate.initialize(e);

        if (e instanceof HibernateProxy) {
            e = (E) ((HibernateProxy) e).getHibernateLazyInitializer().getImplementation();
        }

        return e;
    }

    /**
     * Detach an entity from the hibernate session
     *
     * @param e
     */
    public void evict(E e) {
        logger.trace("Detaching " + entityClass.getSimpleName() + " with ID " + e.getId() + " from hibernate session");
        getSession().evict(e);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions. Call
     * this method without arguments to find all entities.
     * <p>
     * The passed restrictions are combined with a logical AND, the returned
     * entities are distinct root entities.
     *
     * @param restrictions A variable number of query restrictions
     * @return Entities matching the passed query restrictions
     */
    public List<E> findByCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> criteriaQuery = createDistinctRootCriteriaQuery(criteriaBuilder);
        final Root<E> root = criteriaQuery.getRoots().iterator().next();

        applyRestrictions(root, criteriaQuery, criteriaBuilder, restrictions);

        return list(criteriaQuery);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions, but return a
     * stripped version of the entities, where only the fieldNames in <code>restrictFieldNames</code>
     * have their actual values set.
     * <p>
     * You can call this with <code>restrictFieldNames</code> = <code>null</code> to get the full
     * entities back.
     * <p>
     * You can call this method without restriction arguments to find all entities (stripped down to
     * the <code>restrictFieldNames</code>).
     * <p>
     * If this is called as <code>findByCriteriaRestricted(null)</code> the return value equals the
     * return value of <code>findByCriteria()</code>.
     *
     * @param restrictFieldNames
     * @param restrictions
     * @return
     * @throws HibernateException
     */
    public List<E> findByCriteriaRestricted(List<String> restrictFieldNames, QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        if (restrictFieldNames == null || restrictFieldNames.isEmpty()) {
            // no restriction on the fields: return the full entities
            return findByCriteria(restrictions);
        }

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<Object[]> criteriaQuery = criteriaBuilder.createQuery(Object[].class);
        final Root<E> root = criteriaQuery.from(entityClass);

        // select only the requested properties (in the given order)
        final List<jakarta.persistence.criteria.Expression<Object>> selections = new ArrayList<>();
        for (String restrictFieldName : restrictFieldNames) {
            selections.add(root.get(restrictFieldName).as(Object.class));
        }
        criteriaQuery.multiselect(selections);

        applyRestrictions(root, criteriaQuery, criteriaBuilder, restrictions);

        final List<Object[]> tuples = list(criteriaQuery);

        return mapTuplesToEntities(tuples, restrictFieldNames);
    }

    /**
     * Gets the unique result, that matches a variable number of passed
     * restrictions. Returns <code>null</code> if nothing matches.
     *
     * @param restrictions A variable number of query restrictions
     * @return Entity matching the passed query restrictions
     * @throws HibernateException if there is more than one matching result
     */
    public E findByUniqueCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding one unique " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> criteriaQuery = createDistinctRootCriteriaQuery(criteriaBuilder);
        final Root<E> root = criteriaQuery.getRoots().iterator().next();

        applyRestrictions(root, criteriaQuery, criteriaBuilder, restrictions);

        return getSession().createQuery(criteriaQuery)
            .setCacheable(this.useQueryCache)
            .uniqueResult();
    }

    /**
     * Gets the results, that match a variable number of passed restrictions,
     * considering the paging- and sort-info at the same time.
     *
     * @param firstResult Starting index for the paging request.
     * @param maxResults  Max number of result size.
     * @param sorters     The sort orders to apply (optional)
     * @param restrictions A variable number of query restrictions
     * @return
     */
    public PagingResult<E> findByCriteriaWithSortingAndPaging(Integer firstResult,
                                                              Integer maxResults, List<SortOrder> sorters, QueryRestriction<E>... restrictions) throws HibernateException {

        int nrOfSorters = sorters == null ? 0 : sorters.size();

        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria"
            + " with " + nrOfSorters + " sorters");

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> criteriaQuery = createDistinctRootCriteriaQuery(criteriaBuilder);
        final Root<E> root = criteriaQuery.getRoots().iterator().next();

        applyRestrictions(root, criteriaQuery, criteriaBuilder, restrictions);

        // add sort info
        if (sorters != null) {
            final List<Order> orders = new ArrayList<>();
            for (SortOrder sorter : sorters) {
                if (sorter.isAscending()) {
                    orders.add(criteriaBuilder.asc(root.get(sorter.getProperty())));
                } else {
                    orders.add(criteriaBuilder.desc(root.get(sorter.getProperty())));
                }
            }
            if (!orders.isEmpty()) {
                criteriaQuery.orderBy(orders);
            }
        }

        final org.hibernate.query.Query<E> query = getSession().createQuery(criteriaQuery)
            .setCacheable(this.useQueryCache);

        // add paging info
        if (maxResults != null) {
            logger.trace("Limiting result set size to " + maxResults);
            query.setMaxResults(maxResults);
        }
        if (firstResult != null) {
            logger.trace("Setting the first result to be retrieved to "
                + firstResult);
            query.setFirstResult(firstResult);
        }

        return new PagingResult<E>(query.list(), getTotalCount(restrictions));
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link User}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user on the entity.
     *
     * @param user
     * @return
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    public Map<PersistentObject, PermissionCollection> findAllUserPermissionsOfUser(User user) {

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<PersistentObject> criteriaQuery =
            (CriteriaQuery) criteriaBuilder.createQuery(PersistentObject.class);
        final Root<PersistentObject> root = criteriaQuery.from(PersistentObject.class);

        // by only joining the collection, we will only get those entities where
        // there is at least one permission set...
        // it is hard (or even impossible in this scenario) to create a
        // restriction that filters for permissions of the given user only.
        // using HQL here is no option as the PersistentObject is
        // a MappedSuperclass (without table).
        // another efficient way would be a SQL query, but then the SQL
        // would be written in an explicit SQL dialect...
        root.join("userPermissions");
        criteriaQuery.select(root).distinct(true);

        List<PersistentObject> entitiesWithPermissions = getSession().createQuery(criteriaQuery).list();

        Map<PersistentObject, PermissionCollection> userPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<User, PermissionCollection> entityUserPermissions = entity.getUserPermissions();
            if (entityUserPermissions.containsKey(user)) {
                userPermissions.put(entity, entityUserPermissions.get(user));
            }
        }

        return userPermissions;
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link UserGroup}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user group has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user group on the entity.
     *
     * @param userGroup
     * @return
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    public Map<PersistentObject, PermissionCollection> findAllUserGroupPermissionsOfUserGroup(UserGroup userGroup) {

        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<PersistentObject> criteriaQuery =
            (CriteriaQuery) criteriaBuilder.createQuery(PersistentObject.class);
        final Root<PersistentObject> root = criteriaQuery.from(PersistentObject.class);

        // by only joining the collection, we will only get those entities where
        // there is at least one permission set...
        // it is hard (or even impossible in this scenario) to create a
        // restriction that filters for permissions of the given user group only.
        // using HQL here is no option as the PersistentObject is
        // a MappedSuperclass (without table).
        // another efficient way would be a SQL query, but then the SQL
        // would be written in an explicit SQL dialect...
        root.join("groupPermissions");
        criteriaQuery.select(root).distinct(true);

        List<PersistentObject> entitiesWithPermissions = getSession().createQuery(criteriaQuery).list();

        Map<PersistentObject, PermissionCollection> userGroupPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<UserGroup, PermissionCollection> entityUserGroupPermissions = entity.getGroupPermissions();
            if (entityUserGroupPermissions.containsKey(userGroup)) {
                userGroupPermissions.put(entity, entityUserGroupPermissions.get(userGroup));
            }
        }

        return userGroupPermissions;
    }

    /**
     * Returns the total count of db entries for the current type.
     *
     * @param restrictions
     * @return
     */
    public Number getTotalCount(QueryRestriction<E>... restrictions) throws HibernateException {
        final CriteriaBuilder criteriaBuilder = getSession().getCriteriaBuilder();
        final CriteriaQuery<Long> criteriaQuery = criteriaBuilder.createQuery(Long.class);
        final Root<E> root = criteriaQuery.from(entityClass);

        applyRestrictions(root, criteriaQuery, criteriaBuilder, restrictions);

        criteriaQuery.select(criteriaBuilder.countDistinct(root));

        return getSession().createQuery(criteriaQuery).uniqueResult();
    }

    /**
     * @return the entityClass
     */
    public Class<E> getEntityClass() {
        return entityClass;
    }

    /**
     * Helper method: Creates a criteria query for the {@link #entityClass} of
     * this dao, that selects the distinct root entities.
     *
     * @param criteriaBuilder The criteria builder to create the query with
     * @return The created criteria query
     */
    private CriteriaQuery<E> createDistinctRootCriteriaQuery(CriteriaBuilder criteriaBuilder) {
        final CriteriaQuery<E> criteriaQuery = criteriaBuilder.createQuery(entityClass);
        final Root<E> root = criteriaQuery.from(entityClass);
        criteriaQuery.select(root).distinct(true);
        return criteriaQuery;
    }

    /**
     * Helper method: Applies all passed restrictions (if not null) to the
     * given criteria query. The restrictions are combined with a logical AND.
     *
     * @param root            The root of the criteria query
     * @param query           The criteria query to apply the restrictions to
     * @param criteriaBuilder The criteria builder
     * @param restrictions    The restrictions to apply
     */
    private void applyRestrictions(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder criteriaBuilder,
                                   QueryRestriction<E>... restrictions) {
        final List<Predicate> predicates = new ArrayList<>();
        addRestrictionsToPredicates(root, query, criteriaBuilder, restrictions, predicates);
        if (!predicates.isEmpty()) {
            query.where(asPredicateArray(predicates));
        }
    }

    /**
     * Helper method: Adds the predicates of all passed restrictions (if not
     * null) to the given list of predicates.
     *
     * @param root            The root of the criteria query
     * @param query           The criteria query to build the restrictions for
     * @param criteriaBuilder The criteria builder
     * @param restrictions    The restrictions to apply
     * @param predicates      The list of predicates to add to
     */
    private void addRestrictionsToPredicates(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder criteriaBuilder,
                                             QueryRestriction<E>... restrictions, List<Predicate> predicates) {
        if (restrictions == null) {
            return;
        }
        for (QueryRestriction<E> restriction : restrictions) {
            if (restriction == null) {
                continue;
            }
            final Predicate predicate = restriction.toPredicate(root, query, criteriaBuilder);
            if (predicate == null) {
                continue;
            }
            predicates.add(predicate);
        }
    }

    /**
     * Helper method: Returns the given predicates as an array.
     *
     * @param predicates The predicates
     * @return The predicates as array
     */
    private Predicate[] asPredicateArray(List<Predicate> predicates) {
        return predicates.toArray(new Predicate[0]);
    }

    /**
     * Helper method: Returns the number of passed restrictions (accepts null).
     *
     * @param restrictions The restrictions
     * @return The number of restrictions
     */
    private int countRestrictions(QueryRestriction<E>... restrictions) {
        return restrictions == null ? 0 : restrictions.length;
    }

    /**
     * Helper method: Executes the given criteria query and returns the result
     * list. The query is cacheable, depending on the configuration.
     *
     * @param criteriaQuery The criteria query to execute
     * @param <T>           The result type of the query
     * @return The result list
     */
    private <T> List<T> list(CriteriaQuery<T> criteriaQuery) {
        return getSession().createQuery(criteriaQuery)
            .setCacheable(this.useQueryCache)
            .list();
    }

    /**
     * Helper method: Maps the given result tuples (whose elements correspond
     * to the given fieldNames) into instances of the {@link #entityClass},
     * where only the listed fields are set with their actual values.
     *
     * @param tuples             The result tuples
     * @param restrictFieldNames The field names the tuple elements correspond to
     * @return The stripped entities
     */
    private List<E> mapTuplesToEntities(List<Object[]> tuples, List<String> restrictFieldNames) {
        final List<E> entities = new ArrayList<>(tuples.size());

        for (Object[] tuple : tuples) {
            final E entity = instantiateEntity();

            for (int i = 0; i < restrictFieldNames.size(); i++) {
                final String fieldName = restrictFieldNames.get(i);
                writeFieldToEntity(entity, fieldName, tuple[i]);
            }

            entities.add(entity);
        }

        return entities;
    }

    /**
     * Helper method: Creates a new instance of the {@link #entityClass}.
     *
     * @return The new instance
     */
    private E instantiateEntity() {
        try {
            return entityClass.getDeclaredConstructor().newInstance();
        } catch (ReflectiveOperationException e) {
            throw new HibernateException(
                "Could not instantiate an instance of " + entityClass.getName(), e);
        }
    }

    /**
     * Helper method: Writes the given value into the (inaccessible) field of
     * the given entity.
     *
     * @param entity    The entity to write the value to
     * @param fieldName The name of the field to write to
     * @param value     The value to set
     */
    private void writeFieldToEntity(E entity, String fieldName, Object value) {
        final Field field = FieldUtils.getField(entityClass, fieldName, true);
        if (field == null) {
            throw new HibernateException(
                "There is no field '" + fieldName + "' in the type '" + entityClass.getName() + "'");
        }
        try {
            FieldUtils.writeField(field, entity, value, true);
        } catch (IllegalAccessException e) {
            throw new HibernateException(
                "Could not write the value of the field '" + fieldName + "' to an instance of "
                    + entityClass.getName(), e);
        }
    }

}

