    if (!origFieldNamesToCastedValues.isEmpty()) {
        for (Map.Entry<String, List<Object>> entry : origFieldNamesToCastedValues.entrySet()) {
            // if there are multiple values for a field name, we'll check
            // for equality and connect them with OR
            List<Object> fieldValues = entry.getValue();
            final String fieldName = entry.getKey();

            List<QueryRestriction<E>> eqExpressions = new ArrayList<>();

            for (Object fieldValue : fieldValues) {
                final Object castedValue = fieldValue;
                eqExpressions.add((root, query, cb) -> cb.equal(root.get(fieldName), castedValue));
            }

            if (!eqExpressions.isEmpty()) {
                orPredicates.add(
                    (root, query, cb) -> cb.or(
                        toPredicates(root, query, cb, eqExpressions)
                    )
                );
            }
        }

        if (!orPredicates.isEmpty()) {
            // combine all the OR-restrictions with a logical AND
            final QueryRestriction<E> and = (root, query, cb) -> cb.and(
                toPredicates(root, query, cb, orPredicates)
            );
            results = dao.findByCriteriaRestricted(restrictFields, and);
        }
    }

    return results;
}

/**
 * Helper method: Builds the predicates of the given restrictions for the
 * given root, query and criteria builder.
 *
 * @param root        The root of the criteria query
 * @param query       The criteria query
 * @param cb          The criteria builder
 * @param restrictions The restrictions to build the predicates from
 * @param <E>         The entity type
 * @return The built predicates
 */
private static <E> Predicate[] toPredicates(jakarta.persistence.criteria.Root<E> root,
                                            jakarta.persistence.criteria.CriteriaQuery<?> query,
                                            jakarta.persistence.criteria.CriteriaBuilder cb,
                                            List<QueryRestriction<E>> restrictions) {
    List<Predicate> predicates = new ArrayList<>();
    for (QueryRestriction<E> restriction : restrictions) {
        Predicate predicate = restriction.toPredicate(root, query, cb);
        if (predicate != null) {
            predicates.add(predicate);
        }
    }
    return predicates.toArray(new Predicate[0]);
}

