package de.terrestris.shoguncore.hibernate;

import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.usertype.UserType;
import org.joda.time.ReadableDateTime;

import java.io.Serializable;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.sql.Types;
import java.util.Objects;

/**
 * A Hibernate {@link UserType} that maps joda-time {@link ReadableDateTime}
 * values (e.g. the {@link org.joda.time.DateTime} instances used in the
 * SHOGun-Core models) to a JDBC {@link Types#TIMESTAMP} column.
 * <p>
 * This replaces the former jadira usertype
 * {@code org.jadira.usertype.dateandtime.joda.PersistentDateTime}, which is
 * not compatible with Hibernate ORM 6.
 *
 * @author terrestris GmbH &amp; Co. KG
 */
public class JodaDateTimeUserType implements UserType<ReadableDateTime> {

    /**
     * @return The JDBC type code of the column this type is mapped to
     */
    @Override
    public int getSqlType() {
        return Types.TIMESTAMP;
    }

    /**
     * @return The class of the values handled by this type
     */
    @Override
    public Class<ReadableDateTime> returnedClass() {
        return ReadableDateTime.class;
    }

    /**
     * @param x The first value
     * @param y The second value
     * @return Whether the two values are equal
     */
    @Override
    public boolean equals(ReadableDateTime x, ReadableDateTime y) {
        return Objects.equals(x, y);
    }

    /**
     * @param x The value
     * @return The hash code of the value
     */
    @Override
    public int hashCode(ReadableDateTime x) {
        return Objects.hashCode(x);
    }

    /**
     * Reads the value from the given result set.
     *
     * @param rs      The result set to read from
     * @param position The position of the column to read
     * @param session The current session
     * @param owner   The owner of the value
     * @return The read value, or null if the column was null
     * @throws SQLException If reading from the result set fails
     */
    @Override
    public ReadableDateTime nullSafeGet(ResultSet rs, int position, SharedSessionContractImplementor session,
                                         Object owner) throws SQLException {
        final Timestamp timestamp = rs.getTimestamp(position);
        if (timestamp == null) {
            return null;
        }
        return new org.joda.time.DateTime(timestamp.getTime());
    }

    /**
     * Writes the given value to the prepared statement.
     *
     * @param st      The prepared statement to write to
     * @param value   The value to write
     * @param index   The position of the parameter to write
     * @param session The current session
     * @throws SQLException If writing to the statement fails
     */
    @Override
    public void nullSafeSet(PreparedStatement st, ReadableDateTime value, int index,
                            SharedSessionContractImplementor session) throws SQLException {
        if (value == null) {
            st.setNull(index, Types.TIMESTAMP);
        } else {
            st.setTimestamp(index, new Timestamp(value.getMillis()));
        }
    }

    /**
     * joda-time dates are immutable, so the value can be returned as-is.
     *
     * @param value The value to copy
     * @return The value itself
     */
    @Override
    public ReadableDateTime deepCopy(ReadableDateTime value) {
        return value;
    }

    /**
     * joda-time dates are immutable.
     *
     * @return false
     */
    @Override
    public boolean isMutable() {
        return false;
    }

    /**
     * @param value The value to disassemble
     * @return The disassembled (serializable) value
     */
    @Override
    public Serializable disassemble(ReadableDateTime value) {
        return value == null ? null : (Serializable) value;
    }

    /**
     * @param cached The disassembled value
     * @param owner  The owner of the value
     * @return The assembled value
     */
    @Override
    public ReadableDateTime assemble(Serializable cached, Object owner) {
        return cached == null ? null : (ReadableDateTime) cached;
    }
}

