    public LocalDate nullSafeGet(ResultSet rs, int position, SharedSessionContractImplementor session,
                                 Object owner) throws SQLException {
        final Date date = rs.getDate(position);
        if (date == null) {
            return null;
        }
        return LocalDate.fromDateFields(date);
    }

    /**
