     * Public default constructor.
     */
    public ShogunCoreOracleDialect() {
        super();
    }

    /**
     * Registers the column mapping for the LOB datatypes used in
     * SHOGun-Core.
     *
     * @param sqlTypeCode The SQL type code of the column
     * @return The name of the column type
     */
    @Override
    protected String columnType(int sqlTypeCode) {
        switch (sqlTypeCode) {
            case Types.VARBINARY:
                return "blob";
            case Types.LONGVARCHAR:
                return "clob";
            case Types.LONGVARBINARY:
                return "long raw";
            default:
                return super.columnType(sqlTypeCode);
        }
    }
}

